const config=[['Mindo Bird Watching','mindobirdwatching.com'],['The Cloud Forest Retreat','thecloudforestretreat.com'],['Experience Ecuador','experienceecuador.com'],['MindoTours','mindotours.com'],['Choco Andino Tours','chocoandinotours.com'],['Experience The Amazon','experiencetheamazon.com'],['Business Buying and Selling','businessbuyingandselling.com'],['Eyes On Da Nang','eyesondanang.com'],['Arguello Dentistry','arguellodentistry.com']];
const sites=config.map(([name,domain],i)=>({name,domain,stage:i===8?'Monitoring':i?'Developing':'Earning'}));
const nf=new Intl.NumberFormat('en-US'),rows=document.getElementById('sites'),sort=document.getElementById('sort');
let payload=null,requestId=0;const detailState=new Map();const expanded=new Set();
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=v=>v==null?'—':nf.format(v);
const comparisonLabel=()=>document.getElementById('comparison').value==='year'?'last year':'previous period';
const pct=v=>v==null?'—':(100*v).toFixed(2)+'%';
const change=(now,prior)=>now==null||prior==null||prior===0?null:100*(now-prior)/prior;
function delta(v){return v==null?'<span class="delta baseline">— No comparison</span>':`<span class="delta ${v>=0?'up':'down'}">${v>=0?'↑ +':'↓ '}${v.toFixed(1)}%</span>`}
function metric(v,d){return `<td class="number"><b>${number(v)}</b>${delta(d)}</td>`}
function event(s,name){const names=Array.isArray(name)?name:[name];return s.events==null?null:s.events.filter(e=>names.includes(e.name)).reduce((n,e)=>n+e.count,0)}
const formEvents={'mindobirdwatching.com':'form_submit_success','thecloudforestretreat.com':'form_submit_success','experienceecuador.com':'form_submit_success','eyesondanang.com':'generate_lead','mindotours.com':'generate_lead','chocoandinotours.com':'booking_success','experiencetheamazon.com':'lead_submit','businessbuyingandselling.com':'form_submit_success','arguellodentistry.com':['contact_success','appointment_request_success']};
function forms(s){return formEvents[s.domain]?event(s,formEvents[s.domain]):null}
const chartWindows=new Map();let trackingDates=[],trackingReady=false;
function trendPoints(s,key,compact=false){
 const source=key==='sessions'?s.trend:['forms','contacts'].includes(key)?s.conversionTrend:s.searchTrend;if(source==null||!payload?.trendStart)return [];
 const map=new Map(source.map(v=>[v.date,v[key]])),start=key==='sessions'?trackingDates.find(t=>t.domain===s.domain)?.start_date:null,daily=[];
 for(let t=Date.parse(payload.trendStart+'T00:00:00Z');t<=Date.parse(payload.end+'T00:00:00Z');t+=86400000){const date=new Date(t).toISOString().slice(0,10);daily.push({date,end:date,value:start&&date<start&&!(map.get(date)>0)?null:map.get(date)||0});}
 if(compact||chartWindows.get(s.domain+':'+key)!=='weekly')return daily;
 const weeks=[];for(const p of daily){const d=new Date(p.date+'T00:00:00Z'),monday=new Date(+d-((d.getUTCDay()+6)%7)*86400000).toISOString().slice(0,10);let week=weeks.at(-1);if(!week||week.week!==monday){week={date:p.date,end:p.end,week:monday,value:0,recordedDays:0,totalDays:0};weeks.push(week);}week.end=p.end;week.totalDays++;if(p.value!=null){week.value+=p.value;week.recordedDays++;}}return weeks.map(w=>({...w,value:w.recordedDays?w.value:null,partial:w.totalDays<7||w.recordedDays<w.totalDays}));
}
function trend(s,key,compact=false){
 const source=key==='sessions'?s.trend:['forms','contacts'].includes(key)?s.conversionTrend:s.searchTrend;if(source==null||!payload?.trendStart)return '<span class="muted">Trend unavailable</span>';
 const points=trendPoints(s,key,compact),weekly=!compact&&chartWindows.get(s.domain+':'+key)==='weekly',max=Math.max(1,...points.map(p=>p.value||0)),color=key==='impressions'?'#835b15':'#0d5925',x=i=>i/Math.max(1,points.length-1)*220;
 let path='';let connected=false;points.forEach((p,i)=>{if(p.value==null){connected=false;return;}path+=(connected?'L':'M')+x(i).toFixed(1)+','+(48-p.value/max*44).toFixed(1)+' ';connected=true;});
 const dateLabel=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'}),ticks=[0,Math.round((points.length-1)/2),points.length-1],verified=key==='sessions'?trackingDates.find(t=>t.domain===s.domain)?.start_date:null,first=(source||[]).filter(p=>p[key]>0&&p.date>=payload.trendStart&&p.date<=payload.end).sort((a,b)=>a.date.localeCompare(b.date))[0]?.date;
 const marker=(date,label,color)=>{if(!date||date<payload.trendStart||date>payload.end)return '';const i=points.findIndex(p=>date>=p.date&&date<=p.end);if(i<0)return '';return `<g class="recording-marker"><title>${escape(label+' · '+date)}</title><line x1="${x(i)}" x2="${x(i)}" y1="0" y2="49" stroke="${color}" stroke-dasharray="3 2"/></g>`;};
 const context=['forms','contacts'].includes(key)?'Recorded events only; not unique people or confirmed inquiries.':key==='sessions'?(verified?'Confirmed tracking start: '+verified+'. Earlier dates are gaps, not zero traffic.':first?'First recorded session in this window: '+first+'. Installation date unconfirmed; earlier zeros mean no recorded sessions.':'No sessions recorded in this window. Installation date unconfirmed.'):'Search Console impressions reflect recorded Google visibility, independently of GA4 installation.';
 return `<div class="trendchart" data-trend-site="${escape(s.domain)}" data-trend-key="${key}" data-trend-points="${escape(JSON.stringify(points))}" data-trend-max="${max}">${compact?'':`<div class="chart-tools" aria-label="${key} chart interval"><button type="button" data-chart-window="daily" aria-pressed="${!weekly}">Daily</button><button type="button" data-chart-window="weekly" aria-pressed="${weekly}">Weekly</button><span>${weekly?'Calendar weeks · partial edges labelled':['forms','contacts'].includes(key)?'Hover or tap for dates':'Click a day to explore'}</span></div>`}<svg class="spark" viewBox="0 0 220 76" tabindex="0" role="slider" aria-label="${weekly?'Weekly':'Daily'} ${key} over 90 days. Arrow keys select; Enter explores." aria-valuemin="0" aria-valuemax="${points.length-1}" aria-valuenow="${points.length-1}" aria-valuetext="${escape(points.at(-1).date)}: ${points.at(-1).value==null?'tracking not active':points.at(-1).value+' recorded '+key}"><title>${escape(key)} · ${escape(payload.trendStart)} to ${escape(payload.end)} · ${number(points.reduce((n,p)=>n+(p.value||0),0))} recorded</title><path d="M0 49H220" stroke="#d5dfcc"/><path class="chart-series" d="${path}" fill="none" stroke="${color}" stroke-width="2"/>${marker(verified,'Confirmed GA4 installation','#656565')}${!verified&&key==='sessions'?marker(first,'First recorded activity in this window; installation unconfirmed','#656565'):''}<g class="chart-axis" fill="#53634e" font-size="7">${ticks.map((i,j)=>`<text x="${x(i)}" y="65" text-anchor="${j===0?'start':j===2?'end':'middle'}">${dateLabel(points[i].date)}</text>`).join('')}<text x="0" y="9">${number(max)}</text></g><g class="chart-cursor" hidden pointer-events="none"><line y1="0" y2="49" stroke="#53634e" stroke-dasharray="2 2"/><circle r="2.5" fill="${color}" stroke="white" stroke-width="1"/></g></svg><div class="chart-readout" aria-live="polite">Hover or tap for ${weekly?'a dated week':'a date'} and count · arrow keys also work</div>${compact||['forms','contacts'].includes(key)?'':`<button class="explore-point" type="button">Explore selected ${weekly?'week':'day'} →</button><p class="chart-context muted">${escape(context)}</p>`}</div>`;
}
function showTrendPoint(chart,index){const points=JSON.parse(chart.dataset.trendPoints),i=Math.max(0,Math.min(points.length-1,index)),p=points[i],svg=chart.querySelector('svg'),cursor=chart.querySelector('.chart-cursor'),x=220*i/Math.max(1,points.length-1),y=48-p.value/Number(chart.dataset.trendMax)*44;cursor.hidden=false;cursor.removeAttribute('hidden');const line=cursor.querySelector('line');line.setAttribute('x1',x);line.setAttribute('x2',x);const dot=cursor.querySelector('circle');dot.setAttribute('cx',x);dot.setAttribute('cy',y);dot.style.display=p.value==null?'none':'';const date=new Date(p.date+'T12:00:00Z').toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});let label=date+(p.end!==p.date?' → '+p.end:'')+' · '+(p.value==null?'Before confirmed tracking start':number(p.value)+' recorded '+chart.dataset.trendKey)+(p.partial?' · partial week':'');const changes=typeof changeEntries==='undefined'?[]:changeEntries.filter(e=>(e.domain===chart.dataset.trendSite||e.domain==='portfolio')&&e.date>=p.date&&e.date<=p.end);if(changes.length)label+=' · Changes: '+changes.map(e=>e.title).join('; ');chart.querySelector('.chart-readout').textContent=label;svg.setAttribute('aria-valuenow',i);svg.setAttribute('aria-valuetext',label);}
document.addEventListener('pointermove',e=>{const chart=e.target.closest('.trendchart');if(!chart||!e.target.closest('svg'))return;const svg=chart.querySelector('svg'),matrix=svg.getScreenCTM();if(!matrix)return;const x=new DOMPoint(e.clientX,e.clientY).matrixTransform(matrix.inverse()).x;showTrendPoint(chart,Math.round(x/220*(JSON.parse(chart.dataset.trendPoints).length-1)));});
document.addEventListener('pointerdown',e=>{const chart=e.target.closest('.trendchart');if(!chart||!e.target.closest('svg'))return;const svg=chart.querySelector('svg'),matrix=svg.getScreenCTM();if(matrix){const x=new DOMPoint(e.clientX,e.clientY).matrixTransform(matrix.inverse()).x;showTrendPoint(chart,Math.round(x/220*(JSON.parse(chart.dataset.trendPoints).length-1)));}});
document.addEventListener('focusin',e=>{const chart=e.target.closest('.trendchart');if(chart&&e.target.matches('svg'))showTrendPoint(chart,Number(e.target.getAttribute('aria-valuenow')));});
document.addEventListener('keydown',e=>{const chart=e.target.closest('.trendchart');if(!chart||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const svg=chart.querySelector('svg'),i=Number(svg.getAttribute('aria-valuenow')),last=Number(svg.getAttribute('aria-valuemax'));showTrendPoint(chart,e.key==='Home'?0:e.key==='End'?last:i+(e.key==='ArrowRight'?1:-1));});

function smallTable(headers,data){return `<div class="detailtable"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${data.join('')}</tbody></table></div>`}
function searchTable(data,page=false){if(data==null)return '<p class="muted">Search detail unavailable.</p>';if(!data.length)return '<p class="muted">No search rows reported for this period.</p>';return smallTable([page?'Page':'Query','Clicks','Impressions','CTR','Position'],data.slice(0,10).map(r=>`<tr><td class="wraptext">${escape(page?r.url:r.name)}</td><td>${number(r.clicks)}</td><td>${number(r.impressions)}</td><td>${pct(r.ctr)}</td><td>${r.position.toFixed(1)}</td></tr>`))}
function gaTable(data){return data==null?'<p class="muted">Report unavailable.</p>':!data.length?'<p class="muted">No rows reported.</p>':smallTable(['Source / page','Sessions','Change','Engagement'],data.slice(0,10).map(r=>`<tr><td class="wraptext">${escape(r.name)}</td><td>${number(r.sessions)}</td><td>${delta(change(r.sessions,r.priorSessions===0?null:r.priorSessions))}</td><td>${pct(r.sessions?r.engagedSessions/r.sessions:null)}</td></tr>`))}
function movement(current,prior,page=false){if(current==null||prior==null)return '<p class="muted">Comparison unavailable.</p>';const old=new Map(prior.map(r=>[page?r.url:r.name,r]));return smallTable([page?'Page':'Query','Clicks','Click movement','Impressions','Position movement'],current.filter(r=>old.has(page?r.url:r.name)).sort((a,b)=>Math.abs(b.clicks-old.get(page?b.url:b.name).clicks)-Math.abs(a.clicks-old.get(page?a.url:a.name).clicks)).slice(0,10).map(r=>{const o=old.get(page?r.url:r.name),d=r.clicks-o.clicks;return `<tr><td class="wraptext">${escape(page?r.url:r.name)}</td><td>${number(r.clicks)}</td><td>${d>=0?'+':''}${number(d)}</td><td>${number(r.impressions)}</td><td>${(o.position-r.position).toFixed(1)} positions</td></tr>`}))+'<p class="muted">Positive position movement means improvement. Only rows returned in both periods are compared; omitted queries are not treated as zero.</p>'}
function extended(s){const state=detailState.get(s.domain);if(state!=='ready')return `<p class="muted">${state==='error'?'Detailed reports unavailable. Close and reopen to retry.':'Loading page, audience and movement reports…'}</p>`;return `<details class="subdetail"><summary>Landing pages, referrals and campaigns</summary><div class="detailgrid"><article><h3>Landing pages</h3>${gaTable(s.landingPages)}</article><article><h3>Referrals · source / medium</h3>${gaTable(s.referrers)}</article><article><h3>Campaigns</h3>${gaTable(s.campaigns)}</article></div></details><details class="subdetail"><summary>Countries and devices</summary><div class="detailgrid"><article><h3>Visitor countries · GA4</h3>${gaTable(s.analyticsCountries)}</article><article><h3>Visitor devices · GA4</h3>${gaTable(s.analyticsDevices)}</article><article><h3>Search countries · GSC</h3>${searchTable(s.searchCountries)}</article><article><h3>Search devices · GSC</h3>${searchTable(s.searchDevices)}</article></div></details><details class="subdetail"><summary>Search gains and losses</summary><div class="detailgrid"><article><h3>Query movement</h3>${movement(s.queries,s.priorQueries)}</article><article><h3>Page movement</h3>${movement(s.searchPages,s.priorSearchPages,true)}</article></div></details>`}
async function loadDetail(i){const s=sites[i];if(!payload||['ready','loading'].includes(detailState.get(s.domain)))return;const id=requestId,start=payload.start,end=payload.end;detailState.set(s.domain,'loading');render();try{const r=await fetch('/api/portfolio?days='+document.getElementById('days').value+'&compare='+document.getElementById('comparison').value+'&site='+encodeURIComponent(s.domain)+(document.getElementById('include-tests').checked?'&tests=include':''),{cache:'no-store'}),p=await r.json();if(id!==requestId)return;if(!r.ok||!p.ok||!p.details||p.start!==start||p.end!==end)throw Error('Detail unavailable');const data=p.sites.find(x=>x.domain===s.domain);if(!data)throw Error('Site missing');Object.assign(s,data);detailState.set(s.domain,'ready')}catch(e){if(id!==requestId)return;detailState.set(s.domain,'error')}render()}
function detail(s){const rate=s.sessions>0?s.engagedSessions/s.sessions:null;const whatsapp=event(s,'whatsapp_click');const knownForms=forms(s);const observed=(s.events||[]).filter(e=>/lead|form|whatsapp|booking|purchase|contact/i.test(e.name));
 const channels=s.channels==null?'<p>Traffic sources unavailable.</p>':smallTable(['Channel','Sessions','Change'],s.channels.map(c=>`<tr><td>${escape(c.name)}</td><td>${number(c.sessions)}</td><td>${delta(change(c.sessions,c.priorSessions))}</td></tr>`));
 const pages=s.pages==null?'<p>Page data unavailable.</p>':smallTable(['Page','Views'],s.pages.map(p=>`<tr><td class="wraptext">${escape(p.path)}</td><td>${number(p.views)}</td></tr>`));
 const opportunities=s.opportunities==null?'<p>Opportunity data unavailable.</p>':s.opportunities.length?smallTable(['Search query','Impressions','CTR','Position','Review'],s.opportunities.map(o=>`<tr><td class="wraptext"><button class="query-button" data-query="${escape(o.name)}">${escape(o.name)}</button></td><td>${number(o.impressions)}</td><td>${pct(o.ctr)}</td><td>${o.position.toFixed(1)}</td><td>${escape(o.reason)}</td></tr>`)):'<p class="muted">No queries meet the review thresholds this period.</p>';
 const testTraffic=(s.pages||[]).some(p=>/^\/(?:es\/)?testing(?:2)?(?:\/|$)/.test(p.path));const audit=(testTraffic?'Testing pages appear in the most-viewed pages. Traffic and submission events may include QA. ':'')+(formEvents[s.domain]?'Accepted-submission event checked against website code: '+formEvents[s.domain]+'. Counts are events, not unique people or qualified leads. '+(s.domain==='experienceecuador.com'?'Includes trip, contact, partner and concept-interest forms. ':s.domain==='eyesondanang.com'?'Includes one documented launch QA lead on October 2, 2026; do not treat all events as customer inquiries. ':''):(s.events==null?'Event audit unavailable.':'Inquiry tracking needs verification. Observed event names alone do not prove a successful submission.'));
 return `<div class="detailhead"><h3>${s.name}</h3><span class="badge ${s.events==null?'amber':'green'}">${s.events==null?'Analytics detail unavailable':'Analytics detail connected'}</span></div><div class="detailstats"><div><span class="eyebrow">Engagement rate</span><strong>${pct(rate)}</strong><small>${number(s.engagedSessions)} engaged sessions</small></div><div><span class="eyebrow">Successful forms</span><strong>${number(knownForms)}</strong><small>${knownForms==null?'Tracking needs verification':'Submission events'}</small></div><div><span class="eyebrow">WhatsApp clicks</span><strong>${s.domain==='mindobirdwatching.com'||observed.some(e=>e.name==='whatsapp_click')?number(whatsapp):'—'}</strong><small>Interest · not confirmed inquiries</small></div><div><span class="eyebrow">Bookings & revenue</span><strong>—</strong><small>${s.domain==='mindobirdwatching.com'?'Open Business results for CRM outcomes':'Business reporting not connected'}</small></div></div><div class="detailgrid"><article><h3>90-day traffic</h3>${trend(s,'sessions')}<p class="muted">Sessions · ${payload?.trendStart||'—'} → ${payload?.end||'—'}</p></article><article><h3>90-day search visibility</h3>${trend(s,'impressions')}<p class="muted">${chartWindows.get(s.domain+':impressions')==='weekly'?'Calendar-week':'Daily'} impressions · same completed dates</p></article><article><h3>Traffic sources</h3>${channels}</article><article><h3>Most viewed pages</h3>${pages}</article></div><details class="subdetail"><summary>Search opportunities</summary><p class="muted">Review candidates: at least 20 impressions and position 8–20, or at least 100 impressions and CTR below 1%. These are starting points, not ranking guarantees.</p>${opportunities}</details><details class="subdetail"><summary>Top search queries and pages</summary><div class="detailgrid"><article><h3>Search queries</h3>${searchTable(s.queries)}</article><article><h3>Search landing pages</h3>${searchTable(s.searchPages,true)}</article></div><p class="muted">Google returns top rows and may omit anonymized queries. Query totals may differ from the site's total. Positions are averages for each row.</p></details>${extended(s)}<details class="subdetail"><summary>Inquiry tracking audit & data health</summary><p>${audit}</p>${observed.length?smallTable(['Observed event','Current',comparisonLabel()],observed.map(e=>`<tr><td>${escape(e.name)}</td><td>${number(e.count)}</td><td>${number(e.priorCount)}</td></tr>`)):'<p class="muted">No inquiry-related events observed in this period. This does not prove there were no inquiries.</p>'}<p class="muted">${escape(s.analyticsCaveats||'Public website hosts only. Analytics and Search Console use the same completed date range.')} Sources: GA4 ${s.sessions==null?'unavailable':'connected'} · GSC ${s.search==null?'unavailable':'connected'} · Refreshed ${payload?escape(new Date(payload.updatedAt).toLocaleString()):'—'}</p></details><p class="detailinks"><a href="https://${s.domain}/" target="_blank" rel="noopener">Open website ↗</a><a href="https://search.google.com/search-console/performance/search-analytics?resource_id=${encodeURIComponent(['experienceecuador.com','arguellodentistry.com'].includes(s.domain)?'https://'+s.domain+'/':'sc-domain:'+s.domain)}" target="_blank" rel="noopener">Search Console ↗</a>${s.domain==='mindobirdwatching.com'?'<a href="/guest-crm/">Guest CRM ↗</a>':''}</p>`;
}
function render(){let list=[...sites];if(sort.value!=='portfolio')list.sort((a,b)=>(b[sort.value]??-1)-(a[sort.value]??-1));rows.innerHTML=list.map(s=>{const i=sites.indexOf(s),ctr=s.impressions>0?s.clicks/s.impressions:null,previous=s.priorSearch?.impressions>0?s.priorSearch.clicks/s.priorSearch.impressions:null,pp=ctr!=null&&previous!=null?100*(ctr-previous):null;return `<tr class="${i===0?'mindo':''}"><td class="name">${s.name}<span class="domain">${s.domain}</span></td><td><span class="badge ${i===0?'green':''}">${s.stage}</span></td>${metric(s.sessions,change(s.sessions,s.priorSessions),s.priorSessions)}${metric(s.impressions,change(s.impressions,s.priorSearch?.impressions),s.priorSearch?.impressions)}${metric(s.clicks,change(s.clicks,s.priorSearch?.clicks),s.priorSearch?.clicks)}<td class="number"><b>${pct(ctr)}</b><span class="delta baseline">${pp==null?'— No comparison':(pp>=0?'+':'')+pp.toFixed(2)+' pp'}</span></td><td class="number"><b>${number(forms(s))}</b><span class="delta baseline">${formEvents[s.domain]?(s.domain==='eyesondanang.com'?'May include launch QA':s.events?.some(e=>(Array.isArray(formEvents[s.domain])?formEvents[s.domain]:[formEvents[s.domain]]).includes(e.name)&&e.count>0)?'Success event observed':'No success events observed'):'Audit needed'}</span></td><td class="rowtrend">${trend(s,'sessions',true)}</td><td><button class="detailbtn" aria-expanded="${expanded.has(i)}" aria-controls="detail-${i}" aria-label="Details for ${s.name}" data-site="${i}">${expanded.has(i)?'−':'+'}</button></td></tr><tr id="detail-${i}" class="details" ${expanded.has(i)?'':'hidden'}><td colspan="9">${detail(s)}</td></tr>`}).join('')}
const reportDay=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Guayaquil',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());let loadedDay=reportDay();
function quality(){const el=document.getElementById('quality');el.hidden=false;el.textContent=document.getElementById('include-tests').checked?'GA4 includes testing pages. Submission events may include QA.':'GA4 excludes known testing, admin, preview, staging and QA page paths. This does not remove every internal visit or test submission. GSC remains unfiltered.';if(payload&&Date.now()-Date.parse(payload.updatedAt)>86400000)el.textContent+=' Reports are over 24 hours old; refresh before using them.'}

function business(){const b=payload?.business,connected=b?.status==='connected';document.getElementById('business').innerHTML=`<div class="panelhead"><div><h2>Mindo · recorded business outcomes</h2><p class="muted">CRM and accounting records · all recorded channels · selected period</p></div><a href="/guest-crm/">Guest CRM ↗</a></div><div class="detailstats"><div><span class="eyebrow">Inquiries created</span><strong>${number(connected?b.inquiries:null)}</strong>${delta(change(b?.inquiries,b?.prior?.inquiries))}</div><div><span class="eyebrow">Bookings from these inquiries</span><strong>${number(connected?b.confirmed:null)}</strong>${delta(change(b?.confirmed,b?.prior?.confirmed))}<small>${pct(b?.inquiries?b.confirmed/b.inquiries:null)} of created inquiries</small></div><div><span class="eyebrow">Completed tours</span><strong>${number(connected?b.completedTours:null)}</strong>${delta(change(b?.completedTours,b?.prior?.completedTours))}</div><div><span class="eyebrow">Revenue</span><strong>—</strong><small>Revenue reconciliation pending</small></div></div><details class="subdetail"><summary>How these business counts work</summary><p>${connected?escape(b.definitions?.cohort):'Business reporting unavailable; no estimated counts are shown.'}</p><p>${connected?escape(b.definitions?.completed):''}</p><p class="muted">${connected?number(b.missingCreatedDates)+' records lack inquiry creation dates; '+number(b.missingCompletedDates)+' completed records lack dates.':''} These counts are not attributed exclusively to the website. Revenue requires reconciled amounts and payment status.</p></details>`}
function reset(){payload=null;detailState.clear();business();sites.forEach(s=>{const keep={name:s.name,domain:s.domain,stage:s.stage};Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,keep)});quality();render();['sessions','impressions','clicks'].forEach(k=>document.getElementById('total-'+k).textContent='—')}
async function load(){loadedDay=reportDay();const id=++requestId,error=document.getElementById('error');error.hidden=true;document.getElementById('connection').textContent='Refreshing Google reports…';document.getElementById('dates').textContent='Loading completed reporting period…';reset();try{const r=await fetch('/api/portfolio?days='+document.getElementById('days').value+'&compare='+document.getElementById('comparison').value+(document.getElementById('include-tests').checked?'&tests=include':''),{cache:'no-store'}),p=await r.json();if(id!==requestId)return;if(!r.ok||!p.ok||p.version!==3||p.includeTests!==document.getElementById('include-tests').checked)throw Error(p.error||'Reporting unavailable; refresh the page.');payload=p;business();for(const s of sites){const data=p.sites.find(v=>v.domain===s.domain);if(data)Object.assign(s,data,{impressions:data.search?.impressions??null,clicks:data.search?.clicks??null})}quality();render();for(const i of expanded)loadDetail(i);const complete=sites.every(s=>s.sessions!=null&&s.impressions!=null&&s.clicks!=null);document.getElementById('connection').textContent=complete?'Connected · Google reporting':'Partial data · check connections';document.getElementById('connection').parentElement.className='badge '+(complete?'green':'amber');document.getElementById('dates').textContent=p.start+' → '+p.end+(p.comparison==='year'?' · vs '+p.priorStart+' → '+p.priorEnd:'')+' · refreshed '+new Date(p.updatedAt).toLocaleString();for(const k of ['sessions','impressions','clicks'])document.getElementById('total-'+k).textContent=sites.every(s=>s[k]!=null)?number(sites.reduce((n,s)=>n+s[k],0)):'—';if(!complete){error.hidden=false;error.textContent='Some connections are unavailable. Missing values are not counted as zero.'}}catch(e){if(id!==requestId)return;document.getElementById('connection').textContent='Connection required';document.getElementById('dates').textContent='No verified reporting data loaded';error.hidden=false;error.textContent=e.message}}
const refreshDay=()=>{if(!document.hidden&&reportDay()!==loadedDay)load()};setInterval(refreshDay,300000);document.addEventListener('visibilitychange',refreshDay);
document.getElementById('days').addEventListener('change',load);document.getElementById('refresh').addEventListener('click',load);sort.addEventListener('change',render);rows.addEventListener('click',e=>{const b=e.target.closest('button[data-site]');if(!b)return;const i=Number(b.dataset.site);expanded.has(i)?expanded.delete(i):expanded.add(i);const d=document.getElementById(b.getAttribute('aria-controls'));d.hidden=!expanded.has(i);b.setAttribute('aria-expanded',String(expanded.has(i)));b.textContent=d.hidden?'+':'−';if(expanded.has(i))loadDetail(i)});document.getElementById('include-tests').addEventListener('change',load);
